import sys
fh=open('contract/StandardToken.inlined.bytes').read().strip()
assert fh.startswith('0x')
code=bytes.fromhex(fh[2:])

OPS={
0x00:'STOP',0x01:'ADD',0x02:'MUL',0x03:'SUB',0x04:'DIV',0x05:'SDIV',0x06:'MOD',0x0a:'EXP',
0x10:'LT',0x11:'GT',0x12:'SLT',0x13:'SGT',0x14:'EQ',0x15:'ISZERO',0x16:'AND',0x17:'OR',0x18:'XOR',0x19:'NOT',0x1a:'BYTE',0x1b:'SHL',0x1c:'SHR',
0x20:'SHA3',
0x30:'ADDRESS',0x31:'BALANCE',0x32:'ORIGIN',0x33:'CALLER',0x34:'CALLVALUE',0x35:'CALLDATALOAD',0x36:'CALLDATASIZE',0x37:'CALLDATACOPY',0x39:'CODECOPY',0x3a:'GASPRICE',
0x40:'BLOCKHASH',0x41:'COINBASE',0x42:'TIMESTAMP',0x43:'NUMBER',0x44:'DIFFICULTY',0x45:'GASLIMIT',0x46:'CHAINID',0x47:'SELFBALANCE',
0x50:'POP',0x51:'MLOAD',0x52:'MSTORE',0x53:'MSTORE8',0x54:'SLOAD',0x55:'SSTORE',0x56:'JUMP',0x57:'JUMPI',0x58:'PC',0x59:'MSIZE',0x5a:'GAS',0x5b:'JUMPDEST',
0xf0:'CREATE',0xf1:'CALL',0xf2:'CALLCODE',0xf3:'RETURN',0xf4:'DELEGATECALL',0xfd:'REVERT',0xfe:'INVALID',0xff:'SELFDESTRUCT',
0xa0:'LOG0',0xa1:'LOG1',0xa2:'LOG2',0xa3:'LOG3',0xa4:'LOG4',
}
def name(op):
    if 0x60<=op<=0x7f: return 'PUSH%d'%(op-0x5f)
    if 0x80<=op<=0x8f: return 'DUP%d'%(op-0x7f)
    if 0x90<=op<=0x9f: return 'SWAP%d'%(op-0x8f)
    return OPS.get(op,'op_%02x'%op)

def disasm(start,end):
    i=start
    out=[]
    while i<end:
        op=code[i]
        n=name(op)
        if 0x60<=op<=0x7f:
            l=op-0x5f
            arg=code[i+1:i+1+l]
            out.append((i,n,'0x'+arg.hex()))
            i+=1+l
        else:
            out.append((i,n,''))
            i+=1
    return out

a=int(sys.argv[1],16)
b=int(sys.argv[2],16)
for i,n,arg in disasm(a,b):
    print('%04x %-8s %s'%(i,n,arg))

